// The brand marks shown on smart-link cards, as inline SVG path data.
//
// AUTO-GENERATED from simple-icons (v16), and carrying ONLY the providers Lockpad
// recognises — the full package is ~3000 icons and has no business in the bundle.
// Regenerate rather than hand-editing if the provider list changes.
//
// Bundling these locally is the entire point. Recognising that a URL belongs to
// Figma or GitHub and drawing their logo must never involve ASKING Figma or GitHub
// anything: fetching a favicon or an OpenGraph preview would tell those services
// which links sit in a private note, which is precisely the leak this app exists to
// avoid. The marks travel with the app, and the recognition is done by matching URL
// patterns locally (see smartLinkProviders.ts).
//
// TO ADD A PROVIDER: add its icon here and its URL pattern in smartLinkProviders.ts.
// Nothing else changes, and nothing new is requested at runtime.

export interface BrandIcon { title: string; hex: string; path: string }

